L["/agps language auto|enUS|deDE|esES|esMX|frFR|itIT|koKR|ptBR|ruRU|zhCN|zhTW  (AzerothGPS's text; then /reload)"] = "/agps language auto|enUS|deDE|esES|esMX|frFR|itIT|koKR|ptBR|ruRU|zhCN|zhTW  (lingua di AzerothGPS; poi /reload)"
L["AzerothGPS's language: %s. Type /reload to apply it."] = "Lingua di AzerothGPS: %s. Digita /reload per applicarla."
