L["no zone under the crosshair"] = "nessuna zona sotto il mirino"
L["nothing of yours to restore there"] = "niente di tuo da ripristinare qui"
L["put back what was restored (%d of your changes)"] = "rimesso ciò che era stato ripristinato (%d delle tue modifiche)"
L["restored the map's own data there: %d of your changes taken out, %d cut short. Undo puts them back."] = "dati della mappa ripristinati qui: %d delle tue modifiche tolte, %d accorciate. Annulla le rimette."
L["shift-click drawing off"] = "disegno con Maiusc disattivato"
L["shift-click drawing on: Shift + left-drag draws, Shift + right-drag erases, a plain drag pans the map"] = "disegno con Maiusc attivato: Maiusc + trascina col sinistro disegna, Maiusc + trascina col destro cancella, un trascinamento normale sposta la mappa"
L["turn on the road tools or the wall tools first"] = "attiva prima gli strumenti strade o muri"
L["|cff9d9d9dShift-click drawing: hold Shift to draw or erase; a plain drag pans the map|r"] = "|cff9d9d9dDisegno con Maiusc: tieni premuto Maiusc per disegnare o cancellare; un trascinamento normale sposta la mappa|r"
L["|cffe080ffMagic eraser (%d yd): drag over your changes to put the map's own back|r  ·  |cff9d9d9dCtrl + wheel: size  ·  Middle-drag: pan|r"] = "|cffe080ffGomma magica (%d yd): trascina sulle tue modifiche per rimettere quelle della mappa|r  ·  |cff9d9d9dCtrl + rotellina: dimensione  ·  Trascina col centrale: sposta|r"
L["%d min"] = "%d min"
