L["D-pad right"] = "Croce destra"
L["Start"] = "Start"
L["Paddle %s"] = "Paletta %s"
L["D-pad"] = "Croce direzionale"
L["%s: Set Stop   %s: Remove   %s: Back   %s: Zoom   %s: Pan   %s: Recenter"] = "%s: Metti tappa   %s: Togli   %s: Indietro   %s: Zoom   %s: Sposta   %s: Centra"
L["Back can't be left without a button."] = "Indietro deve avere un tasto."
L["Already used: %s"] = "Già in uso: %s"
L["Changes after the fight."] = "Cambia dopo il combattimento."
L["Canceled"] = "Annullato"
L["Controller"] = "Controller"
L["Done"] = "Fatto"
L["Click to change its action."] = "Clicca per cambiarne l'azione."
L["Click a button on the drawing to choose what it does: pressed, held, or with LT, RT, LB or RB."] = "Clicca su un tasto del disegno per scegliere cosa fa: premuto, tenuto premuto o con LT, RT, LB o RB."
L["In Options a controller moves with the D-pad, A selects, B goes back and LB and RB change the page. These buttons are fixed: the buttons assigned above are for the |cffffd100GPS map view only|r."] = "Nelle Opzioni il controller si muove con la croce direzionale, A seleziona, B torna indietro e LB e RB cambiano pagina. Questi tasti sono fissi: i tasti assegnati sopra valgono |cffffd100solo per la vista della mappa GPS|r."
L["Not during a fight."] = "Non durante un combattimento."
L["Pressed"] = "Premuto"
L["No modifier"] = "Nessun modificatore"
L["Pick LT, RT, LB or RB, or Hold."] = "Scegli LT, RT, LB o RB, oppure Tieni."
L["Another line has that one."] = "Un'altra riga ce l'ha già."
L["Sets a stop at the crosshair, or routes to the map icon under it."] = "Mette una tappa al mirino, o porta all'icona della mappa sotto di esso."
L["Answers Yes to a question the map asks, such as removing a stop."] = "Risponde Sì a una domanda della mappa, come rimuovere una tappa."
L["Removes the stop under the crosshair (it asks first)."] = "Rimuove la tappa sotto il mirino (chiede prima)."
L["Goes back: closes the map menu or a question (No), else the map."] = "Torna indietro: chiude il menu della mappa o una domanda (No), altrimenti la mappa."
L["Clears the whole route."] = "Cancella tutto il percorso."
L["Zooms the map in while held."] = "Ingrandisce la mappa finché è premuto."
L["Zooms the map out while held."] = "Rimpicciolisce la mappa finché è premuto."
L["Pans the map up while held."] = "Sposta la mappa in alto finché è premuto."
L["Pans the map down while held."] = "Sposta la mappa in basso finché è premuto."
L["Pans the map left while held."] = "Sposta la mappa a sinistra finché è premuto."
L["Pans the map right while held."] = "Sposta la mappa a destra finché è premuto."
L["Moves the map back to you."] = "Riporta la mappa su di te."
L["Shows or hides AzerothGPS, with the map open or not."] = "Mostra o nasconde AzerothGPS, con la mappa aperta o no."
L["Opens and closes the map menu."] = "Apre e chiude il menu della mappa."
L["Opens AzerothGPS Options."] = "Apre le opzioni di AzerothGPS."
L["Does nothing."] = "Non fa nulla."
L["Select"] = "Seleziona"
L["Apply"] = "Applica"
L["%s comes off %s."] = "%s viene tolto da %s."
L["%s will have no button."] = "%s resterà senza tasto."
L["Mark corners around the nodes to farm: %s adds one at the crosshair  ·  %s: undo  ·  %s: finish  |cff9d9d9d(%s cancels)|r"] = "Segna gli angoli attorno ai nodi da farmare: %s ne aggiunge uno al mirino  ·  %s: annulla  ·  %s: fine  |cff9d9d9d(%s annulla tutto)|r"
L["Mark points at the crosshair with %s  ·  %s: undo  ·  %s: finish  |cff9d9d9d(%s cancels)|r"] = "Segna punti al mirino con %s  ·  %s: annulla  ·  %s: fine  |cff9d9d9d(%s annulla tutto)|r"
L["Mark more corners first."] = "Segna prima altri angoli."
L["Move the map and press %s to mark each corner of a loop around nodes, %s to undo one, and %s (or %s on the first corner) to finish: the route visits every known node inside that's shown (herbs, ore or both), round and round (the nearest 60 at most). %s cancels."] = "Sposta la mappa e premi %s per segnare ogni angolo di un giro attorno ai nodi, %s per toglierne uno e %s (o %s sul primo angolo) per finire: il percorso visita ogni nodo noto mostrato all'interno (erbe, minerali o entrambi), in giro continuo (al massimo i 60 più vicini). %s annulla."
L["%s: Add Corner   %s: Undo Corner   %s: Finish Area   %s: Cancel   %s: Zoom   %s: Pan"] = "%s: Aggiungi angolo   %s: Togli angolo   %s: Finisci area   %s: Annulla   %s: Zoom   %s: Sposta"
L["Add Corner"] = "Aggiungi angolo"
L["Undo Corner"] = "Togli angolo"
L["Finish Area"] = "Finisci area"
L["Mark corners around the example icons with %s, then press %s to finish."] = "Segna gli angoli attorno alle icone di esempio con %s, poi premi %s per finire."
L["With the game's controller UI on, the game keeps its buttons for its own panels: Show/Hide GPS can't be set on one. Make a macro with /agps toggle and put it on a controller button to open/close the map."] = "Con l'interfaccia controller del gioco attiva, il gioco tiene i suoi tasti per i propri pannelli: Mostra/nascondi GPS non si può assegnare a nessuno. Crea una macro con /agps toggle e mettila su un tasto del controller per aprire/chiudere la mappa."
L["Routes through your quest log's objectives and turn-ins, in the fastest order."] = "Ti guida tra gli obiettivi e le consegne del tuo registro missioni, nell'ordine più rapido."
L["Pauses or resumes routing, the stops kept."] = "Mette in pausa o riprende il percorso, le tappe restano."
L["/agps questroute         (the quest route: your quest log's objectives and turn-ins)"] = "/agps questroute         (il percorso missioni: obiettivi e consegne del registro)"
L["Pause when longer by"] = "Pausa se più lungo di"
L["Paused once the time to your stop has grown by this much."] = "In pausa quando il tempo per la tappa è cresciuto di tanto."
L["Clicks what's under the crosshair, as a left-click does: a dungeon's or cave's entrance opens its map, for example."] = "Clicca ciò che è sotto il mirino, come un clic sinistro: l'ingresso di una spedizione o di una grotta ne apre la mappa, per esempio."
L["NOTICE:"] = "AVVISO:"
L["Set Stop"] = "Metti tappa"
L["View Controls"] = "Mostra comandi"
L["Shows the controller's buttons over the map for a while, as Options draws them."] = "Mostra per un po' i tasti del controller sulla mappa, come li disegnano le Opzioni."
L["Show the coordinates (X, Y)"] = "Mostra le coordinate (X, Y)"
L["The X, Y line at the bottom of the map: the spot under the mouse pointer, the crosshair while panning, else you. Off: hidden."] = "La riga X, Y in fondo alla mappa: il punto sotto il puntatore del mouse, il mirino durante lo spostamento, altrimenti tu. Disattivata: nascosta."
L["Undo takes back only what you changed since your last /reload or login. Older roads and walls stay: erase them with the road or wall tools instead."] = "Annulla toglie solo cio che hai cambiato dall'ultimo /reload o accesso. Strade e muri piu vecchi restano: cancellali invece con gli strumenti strade o muri."
L["Ring the flight on the flight map"] = "Cerchia il volo sulla mappa di volo"
L["When the route takes a flight, the flight master it flies to has a ring round it on the flight map, so you can click it straight away."] = "Quando il percorso prende un volo, il maestro di volo di destinazione è cerchiato sulla mappa di volo, così puoi cliccarlo subito."
L["Attach to Map"] = "Aggancia alla Mappa"
L["Puts this panel back at the top of the map."] = "Rimette questo pannello in cima alla mappa."
L["Detach Panel"] = "Sgancia Pannello"
L["Shows this panel in its own window you can drag anywhere. It stays open while the map is closed or minimized, as long as you have a route."] = "Mostra questo pannello in una finestra tutta sua, che puoi trascinare ovunque. Resta aperta mentre la mappa è chiusa o ridotta, finché hai un percorso."
L["Drag to change the panel's width"] = "Trascina per cambiare la larghezza del pannello"
L["Route panel"] = "Pannello del percorso"
L["The bar across the top of the map with the route's distance and times."] = "La barra in cima alla mappa con la distanza e i tempi del percorso."
L["Panel width"] = "Larghezza del pannello"
L["How much of the map's width the panel takes. Dragging its edge on the map sets it too."] = "Quanta parte della larghezza della mappa occupa il pannello. Anche trascinarne il bordo sulla mappa la imposta."
L["Panel position"] = "Posizione del pannello"
L["Middle"] = "Centro"
L["Detach the route panel"] = "Sgancia il pannello del percorso"
L["Shows the panel in its own window you can drag anywhere and resize by its edge. It stays open while the map is closed or minimized (the world map too), as long as you have a route. The button on the panel detaches and attaches it too."] = "Mostra il pannello in una finestra tutta sua, che puoi trascinare ovunque e ridimensionare dal bordo. Resta aperta mentre la mappa è chiusa o ridotta (anche la mappa del mondo), finché hai un percorso. Anche il pulsante sul pannello lo sgancia e lo riaggancia."
L["Hide the buttons"] = "Nascondi i pulsanti"
L["While the panel is detached, it shows only the route's text: no close, Attach, steps or other buttons. Drag it to move it, and right-click it to put it back on the map."] = "Finché il pannello è sganciato, mostra solo il testo del percorso: niente pulsanti di chiusura, aggancio, passi o altro. Trascinalo per spostarlo e fai clic destro su di esso per rimetterlo sulla mappa."
L["Background opacity"] = "Opacità dello sfondo"
L["How dark the detached panel's background is. All the way down, only the text shows. The text always stays fully visible."] = "Quanto è scuro lo sfondo del pannello sganciato. Al minimo si vede solo il testo. Il testo resta sempre del tutto visibile."
L["Drag to move it. Right-click to put it back on the map."] = "Trascina per spostarlo. Clic destro per rimetterlo sulla mappa."
L["Drag to resize the panel"] = "Trascina per ridimensionare il pannello"
L["Lock the panel"] = "Blocca il pannello"
L["While the panel is detached, it can't be dragged, resized, or put back on the map with a right-click. Its buttons still work. The lock button on the panel turns this on and off too."] = "Finché il pannello è sganciato, non si può trascinare, ridimensionare né rimettere sulla mappa con il clic destro. I suoi pulsanti funzionano ancora. Anche il pulsante del lucchetto sul pannello lo attiva e disattiva."
L["Lock Panel"] = "Blocca Pannello"
L["Unlock Panel"] = "Sblocca Pannello"
L["Keeps this panel where it is: no dragging or resizing."] = "Tiene questo pannello dov'è: niente trascinamento né ridimensionamento."
L["Lets you drag and resize this panel again."] = "Ti permette di nuovo di trascinare e ridimensionare questo pannello."
L["Locked. To unlock it: Options > Map window > Lock the panel."] = "Bloccato. Per sbloccarlo: Opzioni > Finestra della mappa > Blocca il pannello."
L["Wrap the text"] = "Manda a capo il testo"
L["While the panel is detached, a line too long for it goes on to the next line instead of being cut short with \"...\". Steps that don't fit still show as \"... N more steps\"."] = "Finché il pannello è sganciato, una riga troppo lunga continua in quella dopo invece di essere tagliata con \"...\". I passi che non ci stanno appaiono ancora come \"... altri N passi\"."
L["|cffffd100Routing paused: it was making your game stutter|r"] = "|cffffd100Percorso in pausa: rendeva il gioco a scatti|r"
L["Routing paused: it was making your game stutter. Resume it with the Pause Routing button or /agps pause."] = "Percorso in pausa: rendeva il gioco a scatti. Riprendilo con il pulsante Pausa percorso o /agps pause."
L["Pause routing when it makes the game stutter"] = "Metti in pausa il percorso quando rende il gioco a scatti"
L["When working out the route keeps slowing frames down, only the way to your next stop is worked out until things are smooth again; if that isn't enough, routing is paused and the chat says so. Resume Routing in the map menu, or /agps pause. Not while the game is in the background."] = "Quando il calcolo del percorso continua a rallentare i fotogrammi, viene calcolato solo il tragitto fino alla prossima tappa finché tutto torna fluido; se non basta, il percorso va in pausa e la chat lo dice. Riprendi percorso nel menu della mappa, o /agps pause. Non mentre il gioco è in secondo piano."
L["Show a Resume button on the minimap square while paused"] = "Mostra un pulsante Riprendi sul riquadro della minimappa in pausa"
L["While routing is paused, a glowing Resume Routing button shows next to the logo in the minimap square's corner. Click it to resume."] = "Mentre il percorso è in pausa, un pulsante \"Riprendi percorso\" brilla accanto al logo nell'angolo del riquadro della minimappa. Fai clic per riprendere."
L["Click to work the route out again from where you are."] = "Clic: il percorso viene ricalcolato da dove ti trovi."
L["Pause/Unpause"] = "Pausa/Riprendi"
